const j = $('Start').first().json;
const toInt = (v, d, max) => Math.min(Math.max(parseInt(v, 10) || d, 1), max);
return [{ json: {
  job_id: j.job_id,
  agent_id: j.agent_id,
  days_back: toInt(j.days_back, 7, 90),
  call_limit: toInt(j.call_limit, 5, 25),
  conversation_ids: Array.isArray(j.conversation_ids) ? j.conversation_ids : [],
  force_reanalyze: j.force_reanalyze === true,
  after_unix: Math.floor(Date.now() / 1000) - toInt(j.days_back, 7, 90) * 86400,
} }];

// Only analyze calls that can teach us something: finished, long enough, real back-and-forth, not voicemail.
const job = $('Load job').first().json;
const f = $('Load config').first().json.qa.filters;
const all = $('List conversations').all().flatMap(i => i.json.conversations ?? []);
const done = new Set($('Read analyzed calls').all().map(i => i.json.conversation_id).filter(Boolean));

let pool = job.conversation_ids.length
  ? all.filter(c => job.conversation_ids.includes(c.conversation_id))
  : all.filter(c => c.status === 'done'
      && (c.call_duration_secs ?? 0) >= f.min_duration_secs
      && (c.message_count ?? 0) >= f.min_messages
      && !/voicemail|silence/i.test(c.termination_reason ?? ''));
if (!job.force_reanalyze) pool = pool.filter(c => !done.has(c.conversation_id));

const picked = pool.sort((a, b) => (b.start_time_unix_secs ?? 0) - (a.start_time_unix_secs ?? 0)).slice(0, job.call_limit);
if (!picked.length) return [{ json: { empty: true } }];
return picked.map(c => ({ json: { conversation_id: c.conversation_id, agent_id: c.agent_id, agent_name: c.agent_name } }));

// Build one evaluation request per call: anonymized transcript + latency stats + agent config snapshot.
const cfg = $('Load config').first().json.qa;
const agent = $('Get agent config').first().json;
const conv = $json;
const RUBRIC = `You are a senior QA reviewer for outbound AI voice agents. You review one real call at a time against the agent's own instructions and configuration.

Rules:
- Judge only what is in the transcript and configuration. Never invent problems. If the call went well, say so and return few or no issues.
- Every issue must cite evidence as a timestamp (e.g. "at 00:42") plus a short paraphrase of what happened.
- Separate the cause: "prompt" (instructions), "settings" (turn-taking, interruptions, LLM/TTS/ASR config), "knowledge" (missing or wrong facts), "tooling" (tools, variables, integrations).
- Fixes must be directly applicable: for prompt issues give the exact text to add or replace; for settings give the setting path and the recommended value.
- Group your test scenarios so one scripted test call can verify several fixes. Maximum 3 scenarios.
- Write every human-readable field in the language given in <language>.

Score each dimension 0-10:
- goal_completion (weight 30): did the call achieve its stated goal, or correctly conclude it could not?
- flow (weight 20): natural turn-taking, no loops, no repeated questions, handles interruptions.
- accuracy (weight 20): correct facts, respects guardrails, no hallucinated promises, uses variables correctly.
- tone (weight 15): clear, concise, adapted to a caller who may be a non-native speaker.
- technical (weight 15): latency, dead air, talk-over, recognition errors.

Return ONLY a JSON object, no prose, no code fences, with this shape:
{
  "scores": { "goal_completion": 0, "flow": 0, "accuracy": 0, "tone": 0, "technical": 0 },
  "overall": 0,
  "verdict": "one sentence",
  "strengths": ["..."],
  "issues": [
    { "severity": "critical|major|minor", "category": "prompt|settings|knowledge|tooling",
      "evidence": "at mm:ss — ...", "root_cause": "...", "fix": "...",
      "prompt_patch": "exact text or null", "setting_change": { "path": "...", "recommended": "..." } }
  ],
  "test_scenarios": [ { "goal": "...", "caller_script": "...", "pass_criteria": ["..."], "covers": [0] } ]
}
"overall" is the weighted score on 0-100.`;

// ── GDPR: remove personal data before it leaves our infrastructure ──
const dv = conv.conversation_initiation_client_data?.dynamic_variables ?? {};
const known = [dv.contact_name, ...(String(dv.contact_name ?? '').split(/\s+/))].filter(s => s && s.length > 2);
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
function anonymize(t) {
  let out = String(t ?? '');
  for (const n of known) out = out.replace(new RegExp(`\\b${esc(n)}\\b`, 'gi'), '[NAME]');
  return out
    .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[EMAIL]')
    .replace(/\+?\d[\d\s().-]{7,}\d/g, '[PHONE]')
    .replace(/\b[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}\b/gi, '[POSTCODE]')
    .replace(/\b\d{1,4}\s+\w+\s+(street|st|road|rd|avenue|ave|lane|rue|boulevard|bd)\b/gi, '[ADDRESS]');
}

const turns = conv.transcript ?? [];
const mmss = s => `${String(Math.floor((s ?? 0) / 60)).padStart(2, '0')}:${String(Math.floor((s ?? 0) % 60)).padStart(2, '0')}`;
const transcript = turns.filter(t => t.message)
  .map(t => `[${mmss(t.time_in_call_secs)}] ${t.role === 'agent' ? 'AGENT' : 'CALLER'}: ${anonymize(t.message)}`).join('\n');

// ── Latency per turn (ms) ──
const series = { llm: [], tts: [], asr: [] };
for (const t of turns) {
  const m = t.conversation_turn_metrics?.metrics ?? {};
  if (m.convai_llm_service_ttfb?.elapsed_time) series.llm.push(m.convai_llm_service_ttfb.elapsed_time * 1000);
  if (m.convai_tts_service_ttfb?.elapsed_time) series.tts.push(m.convai_tts_service_ttfb.elapsed_time * 1000);
  if (m.convai_asr_trailing_service_latency?.elapsed_time) series.asr.push(m.convai_asr_trailing_service_latency.elapsed_time * 1000);
}
const avg = a => (a.length ? Math.round(a.reduce((x, y) => x + y, 0) / a.length) : null);
const p90 = a => (a.length ? Math.round([...a].sort((x, y) => x - y)[Math.floor(a.length * 0.9)] ?? a[a.length - 1]) : null);
const latency = { llm_avg: avg(series.llm), llm_p90: p90(series.llm), tts_avg: avg(series.tts), asr_avg: avg(series.asr),
                  slow_llm_turns: series.llm.filter(v => v > 1500).length, llm_turns: series.llm.length };

// ── Config snapshot (only what matters for behaviour) ──
const cc = agent.conversation_config ?? {};
const prompt = cc.agent?.prompt ?? {};
const snapshot = {
  llm: prompt.llm, temperature: prompt.temperature, max_tokens: prompt.max_tokens,
  tools: (prompt.tools ?? []).map(t => t.name), knowledge_base_docs: (prompt.knowledge_base ?? []).length,
  turn: cc.turn ?? {}, tts: { model_id: cc.tts?.model_id, stability: cc.tts?.stability, speed: cc.tts?.speed },
  language: cc.agent?.language, first_message: cc.agent?.first_message,
};
const language = cc.agent?.language || 'en';

const data = `<language>${language}</language>
<agent_name>${agent.name ?? ''}</agent_name>
<system_prompt>
${prompt.prompt ?? '(unavailable)'}
</system_prompt>
<configuration>${JSON.stringify(snapshot)}</configuration>
<latency_ms>${JSON.stringify(latency)}</latency_ms>
<call duration_secs="${conv.metadata?.call_duration_secs ?? 0}" termination="${conv.metadata?.termination_reason ?? ''}">
${transcript || '(empty transcript)'}
</call>`;

return { json: {
  conversation_id: conv.conversation_id, agent_id: conv.agent_id, agent_name: agent.name ?? conv.agent_name ?? '',
  duration_secs: conv.metadata?.call_duration_secs ?? 0, started_unix: conv.metadata?.start_time_unix_secs ?? null,
  latency, transcript,
  request: {
    model: cfg.model, max_tokens: cfg.max_tokens, temperature: 0,
    system: [{ type: 'text', text: RUBRIC, cache_control: { type: 'ephemeral' } }],   // rubric cached across calls
    messages: [{ role: 'user', content: data }],
  },
} };

// Structured JSON in, structured JSON out — no regex scraping of free text.
const cfg = $('Load config').first().json.qa;
const meta = $('Prepare evaluation').item.json;
const res = $json;
const text = (res.content ?? []).filter(b => b.type === 'text').map(b => b.text).join('').trim();

let evaluation = null, parse_error = null;
try {
  const start = text.indexOf('{'), end = text.lastIndexOf('}');
  evaluation = JSON.parse(text.slice(start, end + 1));
} catch (e) { parse_error = res.error?.message ?? `unparseable model output (${e.message})`; }

const W = { goal_completion: 30, flow: 20, accuracy: 20, tone: 15, technical: 15 };
if (evaluation && typeof evaluation.overall !== 'number' && evaluation.scores) {
  evaluation.overall = Math.round(Object.entries(W).reduce((s, [k, w]) => s + (Number(evaluation.scores[k]) || 0) * w, 0) / 10);
}

const u = res.usage ?? {}; const p = cfg.price_per_mtok;
const cost = [p.input, p.output, p.cache_read, p.cache_write].every(v => typeof v === 'number')
  ? ((u.input_tokens ?? 0) * p.input + (u.output_tokens ?? 0) * p.output +
     (u.cache_read_input_tokens ?? 0) * p.cache_read + (u.cache_creation_input_tokens ?? 0) * p.cache_write) / 1e6
  : null;

const { request, ...rest } = meta;
return { json: { ...rest, evaluation, parse_error, truncated: res.stop_reason === 'max_tokens',
                 usage: u, cost_usd: cost === null ? null : Math.round(cost * 10000) / 10000 } };

// Roll per-call evaluations into a job result the dashboard can render.
const job = $('Load job').first().json;
const calls = $input.all().map(i => i.json);
const ok = calls.filter(c => c.evaluation);
const mean = a => (a.length ? Math.round((a.reduce((x, y) => x + y, 0) / a.length) * 10) / 10 : null);

// Cluster recurring issues across calls (category + normalized fix fingerprint).
const fp = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9àâçéèêëîïôûùüÿñæœ ]/g, '').split(/\s+/).filter(w => w.length > 3).slice(0, 6).join(' ');
const clusters = {};
ok.forEach(c => (c.evaluation.issues ?? []).forEach(iss => {
  const key = `${iss.category}|${fp(iss.fix)}`;
  (clusters[key] ??= { ...iss, occurrences: 0, conversation_ids: [] });
  clusters[key].occurrences++; clusters[key].conversation_ids.push(c.conversation_id);
}));
const rank = { critical: 0, major: 1, minor: 2 };
const recurring = Object.values(clusters).sort((a, b) => b.occurrences - a.occurrences || (rank[a.severity] ?? 3) - (rank[b.severity] ?? 3));

const summary = {
  agent_id: job.agent_id, agent_name: ok[0]?.agent_name ?? calls[0]?.agent_name ?? '',
  calls_analyzed: ok.length, calls_failed: calls.length - ok.length,
  average_score: mean(ok.map(c => c.evaluation.overall)),
  dimension_averages: Object.fromEntries(['goal_completion', 'flow', 'accuracy', 'tone', 'technical']
    .map(k => [k, mean(ok.map(c => Number(c.evaluation.scores?.[k])).filter(Number.isFinite))])),
  latency_ms: { llm_avg: mean(ok.map(c => c.latency.llm_avg).filter(Boolean)), tts_avg: mean(ok.map(c => c.latency.tts_avg).filter(Boolean)) },
  total_cost_usd: ok.some(c => c.cost_usd !== null) ? Math.round(ok.reduce((s, c) => s + (c.cost_usd ?? 0), 0) * 10000) / 10000 : null,
};
const result = { summary, recurring_issues: recurring, calls: calls.map(c => ({ ...c, transcript: c.transcript?.slice(0, 6000) })) };
return [{ json: { job_id: job.job_id, result, analyzed_at: DateTime.now().toUTC().toISO() } }];

const { result, analyzed_at } = $input.first().json;
return result.calls.filter(c => c.evaluation).map(c => ({ json: {
  analyzed_at, agent_id: c.agent_id, agent_name: c.agent_name, conversation_id: c.conversation_id,
  score: c.evaluation.overall, goal_completion: c.evaluation.scores?.goal_completion, flow: c.evaluation.scores?.flow,
  accuracy: c.evaluation.scores?.accuracy, tone: c.evaluation.scores?.tone, technical: c.evaluation.scores?.technical,
  duration_secs: c.duration_secs, llm_avg_ms: c.latency.llm_avg, tts_avg_ms: c.latency.tts_avg, asr_avg_ms: c.latency.asr_avg,
  issues: (c.evaluation.issues ?? []).length, cost_usd: c.cost_usd,
} }));

// Google Sheets cells cap at 50k chars: shed transcripts first if the result is too big.
const { job_id, result } = $input.first().json;
let payload = JSON.stringify(result);
if (payload.length > 48000) { result.calls.forEach(c => { c.transcript = ''; }); payload = JSON.stringify(result); }
if (payload.length > 48000) { result.calls = result.calls.map(({ evaluation, ...c }) => ({ ...c, evaluation: evaluation && { overall: evaluation.overall, verdict: evaluation.verdict } })); payload = JSON.stringify(result); }
return [{ json: { job_id, status: 'done', finished_at: DateTime.now().toUTC().toISO(), result_json: payload } }];

const job = $('Load job').first().json;
return [{ json: { job_id: job.job_id, status: 'done', finished_at: DateTime.now().toUTC().toISO(),
  result_json: JSON.stringify({ summary: { calls_analyzed: 0, message: 'No new qualifying calls in this window' }, recurring_issues: [], calls: [] }) } }];
